"""Physical Education & Yoga - unit notes (Part A of the unit-wise PDFs). Written from the topics that recur in the three past papers
(Unit I Physical Education, II Fitness / diet / obesity, III Yoga, IV Recreation and traditional games, plus Sports & General facts)
and standard textbook knowledge. No syllabus document was supplied, so the unit split follows the website's unit labels."""
from html import escape as _e


def T(head, rows):
    return "<table><tr>" + "".join(f"<th>{h}</th>" for h in head) + "</tr>" + "".join("<tr>" + "".join(f"<td>{c}</td>" for c in r) + "</tr>" for r in rows) + "</table>"


def UL(*a):
    return "<ul>" + "".join(f"<li>{x}</li>" for x in a) + "</ul>"


def OL(*a):
    return "<ol>" + "".join(f"<li>{x}</li>" for x in a) + "</ol>"


def P(s):
    return f"<p>{s}</p>"


def KEY(s):
    return f"<div class='box'><b>Remember:</b> {s}</div>"


def F_BMI():
    return "<div class='box'><b>BMI</b> (Body Mass Index) = weight (kg) / height (m)<sup>2</sup>. It estimates body fat from height and weight.</div>"


UNITS = {}

UNITS["Unit I"] = ("UNIT I", "Physical Education - meaning, aim, scope and development in India", [
    ("1. Meaning and definitions", P("<b>Physical Education (PE)</b> is <b>education THROUGH physical activity</b>: games, sports, exercise, yoga and recreation are used to develop the whole person - body, mind, social behaviour and emotions - not only the muscles. It is a <b>part of total education</b>, so general education and PE are <b>complementary</b>.") + UL("<b>J. F. Williams:</b> \"the sum of man's physical activities selected as to kind and conducted as to outcomes\".", "<b>Charles Bucher:</b> an integral part of the total education process, aimed at developing physically, mentally, emotionally and socially fit citizens through physical activities chosen to achieve these outcomes.", "<b>Focus of PE:</b> \"man in motion\" - the whole person through movement.", "<b>Nature of PE:</b> practical and experiential - learning by doing.") + KEY("Education THROUGH the physical, not education OF the physical only. Aim = all-round development.")),
    ("2. Aim and objectives", P("<b>Aim:</b> the all-round (optimum) development of the individual - physical, mental, social and emotional.") + T(["Objective", "Meaning", "Example"], [["Physical / organic", "Health, strength, endurance, body systems working well", "Running, exercise, yoga"], ["Mental / intellectual", "Alertness, quick decisions, knowledge of rules and health", "Game strategy"], ["Social", "Cooperation, leadership, team spirit, fair play", "Team games"], ["Emotional", "Control of anger, joy in success, acceptance of defeat", "Competition"], ["Skill / neuromuscular", "Coordination and movement skills", "Throwing, catching, jumping"], ["Character", "Honesty, discipline, sportsmanship", "Obeying the umpire"]])),
    ("3. Related terms", T(["Term", "Meaning"], [["Physical training", "Systematic exercise to toughen and condition the body (its major objective is the <b>toughening of the body</b>)"], ["Physical culture", "Systematic development of the body by exercise and health care"], ["Physical activity", "Any bodily movement - a <b>biological necessity</b>"], ["Sports", "Organised competitive physical activity with rules"], ["Recreation", "Enjoyable activity in leisure time that refreshes"]]) + P("<b>German concept of PE:</b> gymnastics was developed by Guts Muths and Jahn; gymnastics is called the <b>mother of all games and sports</b> in the German system.")),
    ("4. Scope and importance", UL("<b>Scope:</b> games and sports, exercise and fitness, yoga, recreation, health education, dance, camping and outdoor education.", "<b>For the individual:</b> fitness, stress relief, self-confidence, discipline.", "<b>For society:</b> teamwork, leadership, national integration, a healthy citizenry.", "<b>Modern need:</b> sedentary habits, stress, obesity and lifestyle diseases make PE more important.", "<b>PE does not</b> claim to cure all diseases; it promotes health and prevention.") + P("<b>Common misconceptions:</b> \"PE is only for athletes\", \"only for boys\", \"a waste of study time\" - all wrong; PE is for every person of every age and supports learning.")),
    ("5. Physical education in India", T(["Period", "Developments"], [["Before independence", "PE was limited and shaped by traditional systems (akhara, wrestling, yoga) and military needs. The <b>Indian Education Commission (Hunter Commission), 1882</b> recognised physical training in schools. <b>YMCA, Madras (1920)</b> started a PE teachers' training college (H. C. Buck)."], ["After independence", "PE linked to national development and school programmes: <b>LNIPE, Gwalior (1957)</b>, <b>NIS, Patiala (1961)</b>, <b>Sports Authority of India (SAI)</b>, national fitness programmes, <b>Khelo India</b> and the <b>Fit India Movement</b>."]]) + KEY("1882 - Hunter Commission; 1920 - YMCA Madras; LNIPE = Gwalior; NIS = Patiala (Diploma in Sports Coaching).") + P("<b>Swami Vivekananda</b> said the youth would be nearer heaven through football than through reading the Gita - stressing a strong body. The saying <b>\"a sound mind in a sound body\"</b> (mens sana in corpore sano) is quoted in PE; examination keys often give Plato - follow your teacher.")),
])

UNITS["Unit II"] = ("UNIT II", "Fitness, wellness, lifestyle, nutrition and obesity", [
    ("1. Fitness and wellness", UL("<b>Physical fitness:</b> the ability to do daily work efficiently, without undue fatigue, and with energy left for leisure and emergencies.", "<b>Health (WHO, 1948):</b> a state of complete physical, mental and social well-being and not merely the absence of disease or infirmity.", "<b>Wellness:</b> a positive state of complete well-being - physical, mental, social, emotional (and spiritual); the scientific meaning is a state of good health and freedom from disease.", "<b>Endorphins</b> released during exercise are called the feel-good hormones - they lift mood and lower stress.") + P("<b>Dimensions of wellness:</b> physical, emotional, social, intellectual, spiritual, occupational and environmental.")),
    ("2. Components of physical fitness", T(["Health-related components (five)", "Meaning"], [["Cardiovascular endurance", "Ability of the heart and lungs to supply oxygen to working muscles for a long time (long-distance running)"], ["Muscular strength", "Maximum force a muscle or muscle group can exert"], ["Muscular endurance", "Ability to repeat or sustain muscle effort"], ["Flexibility", "Range of motion at the joints"], ["Body composition", "Ratio of fat to lean body mass"]]) + T(["Skill-related components", "Meaning"], [["Speed", "Ability to move fast, or cover a distance in minimum time (100 m sprint)"], ["Agility", "Ability to change direction quickly and accurately"], ["Balance", "Ability to maintain the body position"], ["Coordination", "Smooth use of senses and body parts together"], ["Power", "Strength x speed (jump, throw)"], ["Reaction time", "Time taken to respond to a signal"]]) + KEY("Speed and agility are skill-related; reaction time is not one of the five main health-related components. Strength is a <i>conditional</i> ability; balance, agility and rhythm are <i>coordinative</i> abilities. Alertness is a mental state, not a fitness component.")),
    ("3. Lifestyle", UL("<b>Lifestyle</b> = the overall way of living: food, activity, sleep, habits and stress management.", "<b>Healthy lifestyle:</b> balanced diet, regular exercise, enough rest and sleep, no tobacco or alcohol, good hygiene, positive thinking.", "<b>Sedentary lifestyle:</b> lack of physical activity (sitting most of the day); it raises the risk of weight gain, diabetes, heart disease and stress.", "<b>Rest and sleep</b> allow recovery; <b>stress</b> can cause fatigue, poor performance and disturbed sleep.", "<b>\"Health is wealth\":</b> regular exercise and nutritious food keep the body healthy.")),
    ("4. Nutrition and balanced diet", P("A <b>balanced diet</b> contains all nutrients in the right proportion. There are <b>six classes of nutrients</b>: carbohydrates, proteins, fats, vitamins, minerals and water (dietary fibre helps digestion).") + T(["Nutrient", "Function", "Sources / key facts"], [["Carbohydrates", "<b>Main source of energy</b>", "Cereals, potatoes, sugar"], ["Proteins", "Growth and repair of tissues; made of <b>20 amino acids</b> (9 essential)", "Pulses, milk, eggs, meat; <b>soyabean</b> is the richest plant source (about 36-40%)"], ["Fats (lipids)", "Concentrated energy, insulation; fats, oils and waxes are lipids (protein is not)", "Ghee, oils, nuts"], ["Vitamin D", "Absorption of calcium; strong bones - the <b>sunshine vitamin</b>", "Sunlight, milk, fish"], ["Vitamin A", "Vision", "Carrot, papaya, liver"], ["Vitamin C", "Immunity, prevents scurvy", "Citrus fruits, amla"], ["Iron", "Formation of haemoglobin in <b>red blood cells</b>", "Green leafy vegetables, jaggery"], ["Calcium", "Bones and teeth", "Milk, ragi"], ["Water", "Regulates temperature, carries nutrients; adults need about 2-3 litres a day", "Dehydration = low fluid intake"], ["Dietary fibre", "Aids digestion and prevents constipation; gives a feeling of fullness", "Fruits, vegetables, whole grains"]]) + P("<b>Junk food</b> is high in fat, sugar and salt and is not part of a balanced diet.")),
    ("5. Obesity and weight management", UL("<b>Obesity</b> (WHO): abnormal or excessive fat accumulation that may impair health; a person is called obese at about <b>20% above normal weight</b> or <b>BMI of 30 or more</b>.", "<b>Cause:</b> an <b>energy imbalance</b> - more calories taken in than burnt. Contributing: overeating, lack of exercise, genes, hormones and lifestyle.", "<b>Health risks:</b> diabetes, high blood pressure, heart disease, joint problems, breathing problems and some cancers. Insufficient insulin production causes diabetes.") + F_BMI() + T(["BMI (WHO)", "Category"], [["Below 18.5", "Underweight"], ["18.5 - 24.9", "Normal"], ["25 - 29.9", "Overweight"], ["30 and above", "Obese"]]) + UL("<b>Management:</b> balanced diet, regular physical activity, fibre-rich food, healthy snacks (fresh fruit), enough sleep and not skipping breakfast.", "<b>Calorie balance</b> = calories in equal calories out.", "A safe weight-loss rate is about <b>1-2 pounds (0.5-1 kg) a week</b>.") + KEY("BMI = weight in kg / (height in m)<sup>2</sup>; obese = BMI of 30 or more; the best long-term approach is a balanced diet plus regular activity.")),
])


UNITS["Unit III"] = ("UNIT III", "Yoga and meditation", [
    ("1. Meaning, origin and history of yoga", UL("<b>Yoga</b> comes from the Sanskrit root <b>yuj</b> = to join / <b>union</b> (of the individual self with the universal).", "<b>Origin:</b> India; ancient Indian tradition. Yoga is mentioned in the <b>Rigveda</b>, the oldest of the <b>four Vedas</b> (Rig, Yajur, Sama, Atharva); developed in the Upanishads and the Bhagavad Gita.", "<b>Bhagavad Gita</b> - the text behind <b>Karma yoga</b>; <b>Gyana (Jnana) yoga</b> is the path of knowledge and wisdom; also Bhakti yoga (devotion) and Raja yoga.", "<b>Patanjali</b> compiled the <b>Yoga Sutra</b> (the classical, oldest textbook) and is called the founder of the yoga system. Four parts (padas): <b>Samadhi</b> (first), Sadhana, Vibhuti, Kaivalya.", "<b>Definition:</b> \"Yogash chitta vritti nirodhah\" - yoga is the stilling of the fluctuations of the mind (Patanjali).", "<b>Krishnamacharya</b> is called the father of modern yoga.", "<b>International Day of Yoga:</b> 21 June (declared by the United Nations; first held in 2015).", "<b>Aim:</b> spiritual freedom (moksha) and balance of body, mind and spirit.")),
    ("2. Ashtanga yoga - the eight limbs of Patanjali", T(["Limb", "Meaning", "Note"], [["1 Yama", "Social and moral restraints", "<b>5 yamas:</b> ahimsa, satya, asteya, brahmacharya, aparigraha"], ["2 Niyama", "Personal observances (ethical preparation)", "<b>5 niyamas:</b> shaucha, santosha, tapas, svadhyaya, ishvara pranidhana"], ["3 Asana", "Steady, comfortable posture", ""], ["4 Pranayama", "Control of breath", ""], ["5 Pratyahara", "Withdrawal of the senses from outer objects", ""], ["6 Dharana", "Concentration", ""], ["7 Dhyana", "Meditation", ""], ["8 Samadhi", "Complete absorption", "The final stage"]]) + KEY("Yama is the FIRST limb; yama and niyama are the ethical base. External limbs: yama to pratyahara; internal: dharana, dhyana, samadhi. Dhauti is a shatkarma, not one of the eight limbs.")),
    ("3. Shatkarma (six cleansing kriyas) and chakras", T(["Kriya", "Meaning"], [["Neti", "Nasal cleansing - <b>Jala neti</b> (water) and <b>Sutra neti</b> (thread)"], ["Dhauti", "Cleansing of the digestive tract"], ["Nauli", "Abdominal churning"], ["Basti", "Colon cleansing"], ["Trataka", "Steady gazing at a point without blinking"], ["Kapalabhati", "Forceful exhalations - cleans the skull / frontal region"]]) + P("<b>Agnisara kriya</b> (pulling the abdomen in and out) burns abdominal fat. The number of <b>sat karmas = 6</b>.") + T(["Chakra (7)", "Location"], [["Muladhara", "Base of the spine"], ["Svadhisthana", "Lower abdomen"], ["Manipura (solar plexus)", "Upper abdomen / stomach area"], ["Anahata", "Heart"], ["Vishuddha", "Throat"], ["Ajna", "<b>Between the eyebrows</b> (eyebrow centre)"], ["Sahasrara", "Crown of the head"]]) + P("<b>Nadis:</b> Ida (left, cooling), <b>Pingala (right, hot)</b>, Sushumna (central channel).")),
    ("4. Asanas", P("<b>Asana</b> means <b>posture</b> - a steady and comfortable position of the body.") + T(["Asana", "Meaning (English name)", "Main benefit"], [["Padmasana", "Lotus pose", "Best for meditation and pranayama"], ["Vajrasana", "Thunderbolt (diamond) pose", "Improves digestion - the <b>only asana done after meals</b>"], ["Tadasana", "Mountain pose", "Posture, height, balance"], ["Bhujangasana", "Cobra pose", "Strengthens the back, spine flexibility"], ["Dhanurasana", "Bow pose", "Back and abdominal muscles, digestion"], ["Halasana", "Plough pose", "Spine flexibility; supports the thyroid"], ["Naukasana", "Boat pose", "Abdominal strength"], ["Makarasana", "Crocodile pose", "Relaxation, back pain"], ["Shavasana", "Corpse pose", "Total relaxation (done at the end of a session)"], ["Mandukasana", "Frog pose", "Traditionally advised in diabetes"]]) + P("<b>Surya Namaskar</b> (sun salutation) is a sequence of <b>12 postures</b> linked with breathing: Pranamasana, Hastauttanasana (second), Padahastasana, Ashwa Sanchalanasana, Parvatasana, Ashtanga Namaskar, Bhujangasana, and then the reverse back to Pranamasana.") + P("<b>Asana versus exercise:</b> asana is slow, steady, linked with breathing and awareness and aims at <b>body-mind balance</b>; physical exercise is usually faster, aimed at strength and muscle work, with little attention to the mind.")),
    ("5. Pranayama and meditation", UL("<b>Pranayama</b> = prana (breath / life force) + ayama (control) = <b>control of breath</b>; it is systematic and regulated, unlike ordinary deep breathing.", "<b>Three phases:</b> <b>Puraka</b> (inhalation), <b>Kumbhaka</b> (holding the breath) and <b>Rechaka</b> (exhalation).", "<b>Types:</b> Anulom-Vilom (alternate nostril breathing - inhale through one nostril and exhale through the other), Kapalabhati (forceful exhalation; kapala = skull, bhati = shining), Bhastrika (bellows - rapid inhalation and exhalation), Ujjayi (the sound of the sea / waves), Bhramari (humming bee), Sheetali and Sheetkari (cooling).", "<b>Benefits:</b> stronger respiratory system, mental peace, better concentration, control of breath and energy.", "<b>Practice:</b> sit quietly first; best in the calm of morning and evening, on an empty stomach; chess is not a pranayama.") + P("<b>Meditation (Dhyana)</b> is deep, steady concentration of the mind on one point; it is a necessary part of yoga. It reduces stress and increases concentration, and the power of concentration comes through yoga.") + P("<b>Yoga and mental health:</b> reduces stress and anxiety, improves sleep and emotional balance and builds values; <b>yoga and sports:</b> improves flexibility (most of all), concentration, breathing control and injury prevention.")),
])

UNITS["Unit IV"] = ("UNIT IV", "Recreation and traditional games", [
    ("1. Recreation", UL("<b>Recreation</b> = refreshment and joy: an enjoyable activity done in <b>leisure time</b> that refreshes body and mind (re-creation).", "<b>General principle:</b> enjoyment - voluntary, pleasure-giving and free from compulsion.", "<b>Scope:</b> sports, dance, music, hobbies, camping, tours, drama, aerobics, Zumba (a dance fitness activity).", "<b>Indoor examples:</b> chess, carrom, table tennis. <b>Outdoor examples:</b> camping, trekking, picnics, swimming.", "<b>Importance:</b> reduces stress and boredom, builds social bonds, health and creativity, and provides positive use of leisure.", "<b>Relation with PE:</b> both promote physical and mental well-being; recreation provides fun, relaxation and social contact that PE uses to build character.", "<b>Planning:</b> a good programme should be varied, safe, voluntary, suited to age and interest, and should consider <b>geographical and climatic conditions</b> when planning outdoor activities.", "<b>H. C. Buck</b> (YMCA) is credited with starting organised physical education and recreation in India.")),
    ("2. Traditional games", P("<b>Traditional games</b> are games rooted in a culture, played with simple rules and local, low-cost materials. They are generally outdoor, played in villages and streets, and help preserve culture, build physical skills, social bonding, balance and coordination.") + T(["Game", "Equipment", "How it is played", "Key terms"], [["<b>Gilli-Danda</b>", "<b>Two</b> sticks - a long stick (<b>danda</b>) and a small wooden piece (<b>gilli</b>)", "Outdoor; the gilli is flicked and struck with the danda; distance is measured", "Played in many Indian villages"], ["<b>Kanche</b> (marbles / <b>gutte</b> in some regions)", "Glass marbles (kanche); small stones for gutte", "Players flick a shooter marble at others placed in a circle; soft soil or ground is best", "Shooter = <b>gota</b>; <b>kacchi</b> = a wrong / faulty shot"], ["<b>Stapu</b> (hopscotch)", "Chalk-drawn boxes and a marker stone (<b>thippi</b>)", "Throw the stone into a box and <b>hop on one leg</b> through the boxes; if the stone lands on the line you lose the turn", "Develops balance and coordination"], ["<b>Gatte</b> (five stones)", "<b>5</b> small stones", "Toss and catch stones in different steps", "Hand-eye coordination"]]) + KEY("Gilli-Danda: two sticks, gilli is the small one. Marbles = kanche; stapu = hopscotch; gatte uses 5 stones; stone on the line in stapu = lose the turn.") + UL("<b>Benefits:</b> fitness, balance, hand-eye coordination, teamwork, creativity and cultural pride at low cost.", "<b>Design of a traditional game:</b> use simple rules and local materials.", "<b>Why promote them:</b> they are cheap, inclusive, safe, culturally valuable and keep children active and away from screens.")),
])

UNITS["Sports & General"] = ("SPORTS AND GENERAL", "Anatomy and health facts, Olympics, sports rules and institutions (asked in the papers)", [
    ("1. Anatomy and health facts", T(["Fact", "Answer"], [["Types of muscles", "Three - skeletal, smooth, cardiac"], ["Muscle weight in the body", "About 40-45% of body weight"], ["Number of muscles", "639 (about)"], ["Anatomy", "Study of body structure"], ["Bones in the cranium", "8"], ["Normal body temperature", "37 °C (98.6 °F)"], ["Resting heart rate of an adult", "About 72 beats a minute"], ["System that produces movement", "Muscular system"], ["Trachea (windpipe)", "Part of the respiratory tract"], ["WHO established", "7 April 1948"], ["CPR - checking for breathing", "No longer than 10 seconds"]]) + UL("<b>Growth and development</b> are affected by heredity, nutrition and environment.", "<b>Cheating</b> = deliberately using deception to gain an unfair advantage.")),
    ("2. Olympics and Asian Games", T(["Item", "Fact"], [["Ancient Olympics", "Held at Olympia, Greece, in honour of <b>Zeus</b>"], ["Modern Olympics began", "<b>Athens, 1896</b> (first modern Games); Pierre de Coubertin"], ["Interval", "Every <b>4 years</b>; the Games last about <b>16 days</b>"], ["Rings", "Five rings = five continents"], ["Motto", "<b>Citius, Altius, Fortius</b> (Faster, Higher, Stronger) - proposed by Father Henri Didon"], ["First Asian Games", "<b>India (New Delhi), 1951</b>"], ["First Indian woman to win a gold at the Asian Games", "Kamaljeet Sandhu (1970)"]])),
    ("3. Sports facts and institutions", T(["Item", "Fact"], [["Players in a football / hockey / cricket team", "11 each"], ["Umpires on the field in cricket", "2"], ["Ways of getting out in cricket", "10 (types of out)"], ["Popping crease", "Cricket"], ["Marathon", "42.195 km"], ["Kabaddi", "Originated in India"], ["Kho-Kho chasers' squares", "30 cm x 35 cm"], ["Volleyball antenna height", "1.80 m"], ["Saina Nehwal", "Badminton"], ["Mother of sports", "Athletics"], ["Mother of all games and sports (German concept)", "Gymnastics"], ["National Sports Day", "29 August (birthday of Major Dhyan Chand)"], ["Arjuna Award", "Presented by the President of India"], ["LNIPE", "Gwalior"], ["NIS", "Patiala - Diploma in Sports Coaching"], ["SAI", "Sports Authority of India"], ["If the number of teams is not a power of two", "Byes are given"], ["Not in women's gymnastics", "Pommel horse"]])),
    ("4. Teaching and education", UL("<b>Goal of teaching:</b> desirable change in behaviour.", "<b>Indirect teaching</b> is student-centred.", "The quality of a school's education depends on the quality of teacher education.", "A teacher develops social values mainly by <b>behaving ideally</b> - being a role model.", "A modern PE teacher is a <b>movement educator</b>.")),
])
